// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0) && actor != address(this));
        // owner opens the game to the public
        c.OpenToThePublic();
        // betLimit is 0, so any EOA player can wager with value 0
        vm.startPrank(actor, actor); // ensures msg.sender == tx.origin (onlyRealPeople)
        bool ok;
        try c.wager{value: 0}() { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(ok);
    }
}
